-- 4 subjects, 38 chapters. Upsert only: removing a chapter here never cascades into content.

MERGE INTO subjects AS t
USING (VALUES
        ('accounts', 'acc11', 11, 'Book-Keeping and Accountancy', 1),
        ('economics', 'eco11', 11, 'Economics', 2),
        ('maths1', 'mth11a', 11, 'Mathematics & Statistics Part 1', 3),
        ('maths2', 'mth11b', 11, 'Mathematics & Statistics Part 2', 4)
) AS s (code, short_code, grade, name, sort_order)
ON t.code = s.code
WHEN MATCHED AND (t.short_code, t.grade, t.name, t.sort_order) IS DISTINCT FROM (s.short_code, s.grade, s.name, s.sort_order) THEN
    UPDATE SET short_code = s.short_code, grade = s.grade, name = s.name, sort_order = s.sort_order
WHEN NOT MATCHED THEN
    INSERT (code, short_code, grade, name, sort_order) VALUES (s.code, s.short_code, s.grade, s.name, s.sort_order);

